/* Actual 8088 cdecl/software-arithmetic fixture for Breadboard XT, SPEC130.
 * Expected packed binary64 words are independently generated by host Python.
 * N toggles an intentionally wrong expected answer (negative control). */
#include "os88.h"
#include "../../apps/breadxt/bb.h"
BBWord bb_num_error;
BBByte bb_fp_scratch[76];
static BBNum bn_a,bn_b,bn_c,bn_before;
static unsigned bn_pass,bn_fail,bn_done,bn_negative,bn_case;
static void *bn_win;
static struct os88_pt bn_org;
static char bn_line[48],bn_num[8];
static BBByte bn_plot[4];
void bx_setup(unsigned seg,void *band,unsigned cap,unsigned artseg,int bpp);
void bx_new(int x,int y,int w,int h,int colour);
void bx_fill(int x1,int y1,int x2,int y2,int colour);
void bx_dots(int x1,int y1,int x2,int y2,int step,int colour);
void bb_alertdone(int button) { (void)button; }
#include "expected.inc"
static void bn_check(int ok)
{
    bn_case++;
    if (bn_negative && bn_case==1) ok=0;
    if(ok) bn_pass++; else bn_fail++;
}
static int bn_equal(const BBNum *a,const BBNum *b)
{
    return a->w[0]==b->w[0] && a->w[1]==b->w[1] &&
           a->w[2]==b->w[2] && a->w[3]==b->w[3];
}
static void bn_test(void)
{
    unsigned i;
    bn_pass=0;bn_fail=0;bn_case=0;bb_num_error=0;
    bb_nuint(&bn_a,65535u);bn_check(bn_equal(&bn_a,&bn_e65535));
    bb_nset(&bn_b,-12345);bn_check(bn_equal(&bn_b,&bn_em12345));
    bb_nset(&bn_a,3);bb_nset(&bn_b,4);
    bn_check(bb_nop(&bn_a,&bn_a,&bn_b,BB_NADD) && bn_equal(&bn_a,&bn_e7));
    bb_nset(&bn_a,-7);bb_nset(&bn_b,5);
    bn_check(bb_nop(&bn_b,&bn_a,&bn_b,BB_NSUB) && bn_equal(&bn_b,&bn_em12));
    bb_nset(&bn_a,300);bb_nset(&bn_b,200);
    bn_check(bb_nop(&bn_c,&bn_a,&bn_b,BB_NMUL) && bn_equal(&bn_c,&bn_e60000));
    bn_check(bb_nop(&bn_c,&bn_c,&bn_a,BB_NDIV) && bb_nround(&bn_c)==200);
    bb_nset(&bn_a,1);bb_nset(&bn_b,3);
    bn_check(bb_nop(&bn_c,&bn_a,&bn_b,BB_NDIV) && bn_equal(&bn_c,&bn_ethird));
    bb_nset(&bn_a,-3);bb_nset(&bn_b,2);bb_nop(&bn_c,&bn_a,&bn_b,BB_NDIV);
    bn_check(bb_nround(&bn_c)==-2 && !bb_num_error);
    bb_nset(&bn_a,3);bb_nop(&bn_c,&bn_a,&bn_b,BB_NDIV);
    bn_check(bb_nround(&bn_c)==2 && !bb_num_error);
    bn_check(bb_ncmp(&bn_a,&bn_b)>0 && bb_ncmp(&bn_b,&bn_a)<0 &&
             bb_ncmp(&bn_a,&bn_a)==0);
    bb_nset(&bn_c,17);os88_memcpy(&bn_before,&bn_c,sizeof(BBNum));
    bb_nset(&bn_b,0);bb_num_error=0;
    bn_check(!bb_nop(&bn_c,&bn_a,&bn_b,BB_NDIV) &&
             bb_num_error && bn_equal(&bn_c,&bn_before));
    bb_num_error=0;bb_nuint(&bn_a,65535u);bb_nround(&bn_a);
    bn_check(bb_num_error==BB_ENUMERIC);
    bb_num_error=0;bb_nset(&bn_a,32767);bb_nset(&bn_b,32767);
    bb_nop(&bn_c,&bn_a,&bn_b,BB_NMUL);
    bn_check(!bb_nop(&bn_c,&bn_c,&bn_a,BB_NMUL) && bb_num_error);
    /* The face's drawing core (SPEC.md 130.6.2) under the actual C ABI, on
     * a 1bpp band 16x2 in this segment: a solid white row is FFh FFh, and
     * channel B's dotted trace assembled from tiny sample/hold spans keeps
     * its spatial phase - every even x lit, 10101010, not a solid FFh. */
    bx_setup(0,bn_plot,4,0,1);bx_new(0,0,16,2,0);
    for(i=0;i<16;i+=2){
        bx_fill(i,0,i+1,0,15);
        bx_dots(i,1,i+1,1,2,15);
    }
    bn_check(bn_plot[0]==255 && bn_plot[1]==255);
    bn_check(bn_plot[2]==0xAA && bn_plot[3]==0xAA);
    bb_num_error=0;bn_done=1;
}
void os88_paint(void *win)
{
    os88_wm_content(win,&bn_org);
    os88_font_run(bn_org.x+8,bn_org.y+8,"Breadboard XT numeric fixture",0,15);
    os88_strcpy(bn_line,bn_done?(bn_fail?"FAIL ":"PASS "):"Pending ",48);
    os88_utoa(bn_pass,bn_num);os88_strcpy(bn_line+os88_strlen(bn_line),bn_num,32);
    os88_strcpy(bn_line+os88_strlen(bn_line)," passed, ",24);
    os88_utoa(bn_fail,bn_num);os88_strcpy(bn_line+os88_strlen(bn_line),bn_num,16);
    os88_strcpy(bn_line+os88_strlen(bn_line)," failed",12);
    os88_font_run(bn_org.x+8,bn_org.y+24,bn_line,0,15);
    os88_font_run(bn_org.x+8,bn_org.y+40,"N: negative control",0,15);
}
void os88_onkey(int ascii,int scan,void *win)
{
    (void)scan;
    if(ascii=='n'||ascii=='N'){
        bn_negative=!bn_negative;bn_done=0;os88_wm_wake(win);
    }
}
void os88_onwake(void *win)
{
    if(!bn_done) bn_test();
    os88_gfx_lock();
    if(os88_wm_clip_set(win)==0){os88_paint(win);os88_wm_grow(win);}
    os88_gfx_unlock();
}
static struct os88_class bn_cls={OS88_CLASS_LEN,0,
    os88_t_paint,os88_t_onkey,0,0,os88_t_onwake,0,0,0,0,0,0,0,0};
void *os88_main(void)
{
    bn_win=os88_wm_create(112,64,344,88,"Breadboard XT numeric",&bn_cls);
    if(bn_win) os88_wm_wake(bn_win);
    return bn_win;
}
